class Solution {
public:
    int longestConsecutive(vector<int>& nums) {
        unordered_set<int> s(nums.begin(), nums.end());
        int best = 0;
        for (int x : s) {
            if (s.count(x - 1)) continue; // not the start of a sequence
            long long y = x;
            while (y + 1 <= INT_MAX && s.count((int)(y + 1))) y++;
            best = max(best, (int)(y - x + 1));
        }
        return best;
    }
};
